CREATE TABLE `SchoolProfile` (`id` VARCHAR(191) NOT NULL DEFAULT 'main',`pageTitle` VARCHAR(191) NOT NULL,`introduction` TEXT NOT NULL,`principalName` VARCHAR(191) NOT NULL,`principalPhoto` VARCHAR(191) NULL,`welcomeMessage` LONGTEXT NOT NULL,`schoolName` VARCHAR(191) NOT NULL,`npsn` VARCHAR(191) NOT NULL,`accreditation` VARCHAR(191) NOT NULL,`foundedYear` VARCHAR(191) NOT NULL,`operationalPermit` VARCHAR(191) NOT NULL,`permitIssuer` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `SchoolHistory` (`id` VARCHAR(191) NOT NULL DEFAULT 'main',`pageTitle` VARCHAR(191) NOT NULL,`introduction` TEXT NOT NULL,`storyTitle` VARCHAR(191) NOT NULL,`story` LONGTEXT NOT NULL,`image` VARCHAR(191) NULL,`milestones` JSON NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `FacilitySettings` (`id` VARCHAR(191) NOT NULL DEFAULT 'main',`pageTitle` VARCHAR(191) NOT NULL,`introduction` TEXT NOT NULL,`facilities` JSON NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
